// Offline support for the web app. Every request goes to the network first,
// so a new deploy shows up on the next load; the last good copy is served
// when the network is down. Only same-origin GET requests are handled.
'use strict';

const CACHE = 'demonica-v1';

self.addEventListener('install', () => self.skipWaiting());

// Every page is the same app (GitHub Pages serves deep links from
// 404.html), so navigations share one cache entry: the app shell.
const isPage = request.mode === 'navigate';
const key = isPage ? self.registration.scope : request;

// Flutter's own service worker no longer caches anything, so Demonica
// registers sw.js (network first, cached copy when offline) instead. The URL
// is resolved against <base href> so deep links register the same worker.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register(new URL('sw.js', document.baseURI));
  });
}

// Applies the chosen theme before the page paints, to avoid a flash.
// Only the word "light" or "dark" is stored on this device; it identifies no one.
try {
  document.documentElement.dataset.theme = localStorage.getItem('theme') || 'light'
} catch {}

// Content check, step 0 (offline): every reference has a year and a link (ABC-223).
//
//   node scripts/x.mjs
import { readFile } from 'node:fs/promises'

/** Every reference without a year or a link, as `id: problem` lines. */
export function problems(refs) {
  return refs.filter((r) => !r.year || !r.url).map((r) => `${r.id}: missing year or link`)
}
